function o(t){if(!t)return"0 B";const e=["B","KB","MB","GB","TB"];let n=0,r=Number(t);for(;r>=1024&&n<e.length-1;)r/=1024,n++;return`${r.toFixed(r>=10||n===0?0:1)} ${e[n]}`}function u(t){if(t==null||t===0)return"-";if(t<1e3)return`${t} ms`;const e=Math.floor(t/1e3);if(e<60)return`${e} 秒`;const n=Math.floor(e/60);return n<60?`${n} 分 ${e%60} 秒`:`${Math.floor(n/60)} 小时 ${n%60} 分`}function a(t){if(!t)return"-";const e=new Date(t),n=r=>String(r).padStart(2,"0");return`${e.getFullYear()}-${n(e.getMonth()+1)}-${n(e.getDate())} ${n(e.getHours())}:${n(e.getMinutes())}:${n(e.getSeconds())}`}function i(t){return{eof:"正常关闭",timeout:"空闲超时",reset:"连接重置",rejected:"被拒绝",target_unreachable:"目标不可达",client_offline:"客户端离线",server_shutdown:"服务端关闭",unclean:"异常中断"}[t]||t||"-"}export{u as a,a as b,i as c,o as f};
